                const textareaElement = window.parent.document.getElementById('send_textarea');
                if (textareaElement) {
                  textareaElement.value = message;
                  const sendButton = window.parent.document.getElementById('send_but');
                  if (sendButton) {
                    sendButton.click();
                    console.log('已尝试通过DOM操作发送消息');
                    return true;
                  }
                }
              } catch (e) {
                console.log('DOM操作失败:', e);
              }
            }

            return false;
          } catch (error) {
            console.error('发送消息到SillyTavern失败:', error);
            return false;
          }
        };

        // 监听来自SillyTavern的消息
        window.addEventListener('message', function(event) {
          if (event.data.type === 'from_sillytavern') {
            console.log('收到ST消息:', event.data.data);
          }
        });

        // 通知ST页面live.html已加载
        // setTimeout(function() {
        //   window.sendToSillyTavern('【系统消息】直播页面已加载');
        //   console.log('发送了加载通知到ST');
        // }, 1000);
      })();

      // 添加剧情弹幕池
      const scriptedDanmakuPool = {
        danmakuList: [], // 存储解析的4条剧情弹幕
        currentIndex: 0,

        // 添加剧情弹幕
        setDanmakuList(danmakuList) {
          this.danmakuList = danmakuList;
          this.currentIndex = 0;
        },

        // 获取下一条剧情弹幕
        getNextDanmaku() {
          if (this.danmakuList.length === 0) return null;

          const danmaku = this.danmakuList[this.currentIndex];
          this.currentIndex = (this.currentIndex + 1) % this.danmakuList.length;
          return danmaku;
        }
      };

      // 解析<danmaku>标记的函数
      function parseDanmakuContent(contentStr) {
        const danmakuPattern = /<danmaku>([\s\S]*?)<\/danmaku>/;
        const danmakuMatch = contentStr.match(danmakuPattern);

        if (danmakuMatch && danmakuMatch[1]) {
          // 获取<danmaku>标记内的内容
          const danmakuContent = danmakuMatch[1].trim();
          // 按行分割
          const lines = danmakuContent.split('\n');

          // 解析每行弹幕（粉丝ID|弹幕内容）
          const parsedDanmakus = [];
          lines.forEach(line => {
            const trimmedLine = line.trim();
            if (trimmedLine) { // 跳过空行
              const parts = trimmedLine.split('|');
              if (parts.length >= 2) {
                parsedDanmakus.push({
                  user: parts[0].trim(),
                  content: parts.slice(1).join('|').trim(),
                  isScripted: true // 标记为剧情弹幕
                });
              }
            }
          });

          return parsedDanmakus;
        }

        return [];
      }

      // 解析整个liveContentExample内容
      function parseAllContent(contentStr) {
        // 解析danmaku部分并设置到剧情弹幕池
        const scriptedDanmakus = parseDanmakuContent(contentStr);
        if (scriptedDanmakus.length > 0) {
          scriptedDanmakuPool.setDanmakuList(scriptedDanmakus);
          console.log(`成功解析 ${scriptedDanmakus.length} 条剧情弹幕`);
        }

        return contentStr; // 返回原始内容以便其他解析函数处理
      }
    </script>
