      ];

      // 随机选择背景图片
      function randomizeBackground() {
        const randomIndex = Math.floor(Math.random() * backgroundImages.length);
        const selectedImage = backgroundImages[randomIndex];

        // 更新横屏模式的背景图片
        document.querySelector(".landscape-content img").src = selectedImage;

        // 更新livebg图片
        const livebgImg = document.querySelector(".livebg-image");
        if (livebgImg) {
          livebgImg.src = selectedImage;
          document.querySelector(".livebg-container").classList.add("show");
        }
      }

      // 添加与文本对应的图片数组
      const textImagePairs = [
        {
          text: "在这里显示文本内容",
          //   image: "https://files.catbox.moe/0bv8nc.jpg",
        },
        {
          text: "第二段文本内容示例，第二段文本内容示例。第二段文本内容示例，第二段文本内容示例。",
          //   image: "https://files.catbox.moe/8bdvbd.png",
