      // 解析<live>标记的函数
      function parseLiveContent(liveContentStr) {
        // 创建新的文本-图片对数组
        const newTextImagePairs = [];

        // 使用正则表达式解析<live>标记内的内容
        const livePattern = /<live>([\s\S]*?)<\/live>/;
        const liveMatch = liveContentStr.match(livePattern);

        // 解析背景图片标签
        let backgroundInfo = null;
        const bgPattern = /<livebg>([\s\S]*?)<\/livebg>/;
        const bgMatch = liveContentStr.match(bgPattern);
        if (bgMatch && bgMatch[1]) {
          backgroundInfo = bgMatch[1].trim();
        }

        // 解析直播间标题
        let liveTitle = null;
        const titlePattern = /<livetitle>([\s\S]*?)<\/livetitle>/;
        const titleMatch = liveContentStr.match(titlePattern);
        if (titleMatch && titleMatch[1]) {
          liveTitle = titleMatch[1].trim();
          console.log("找到直播间标题:", liveTitle); // 添加调试输出

          // 立即更新DOM中的直播间标题
          document.addEventListener("DOMContentLoaded", () => {
            const userNameElement = document.querySelector(".user-name");
            if (userNameElement) {
              userNameElement.textContent = liveTitle;
              console.log("DOMContentLoaded: 直播间标题已设置为", liveTitle);
            }
          });

          // 如果DOM已经加载完成，则立即设置
          if (
            document.readyState === "complete" ||
            document.readyState === "interactive"
          ) {
            const userNameElement = document.querySelector(".user-name");
            if (userNameElement) {
              userNameElement.textContent = liveTitle;
              console.log("立即设置: 直播间标题已设置为", liveTitle);
            }
          }
        }

        // 提取用户ID
        let userID = "user的大手"; // 默认用户名
        const userIDPattern = /<userID>([\s\S]*?)<\/userID>/;
        const userIDMatch = liveContentStr.match(userIDPattern);
        if (userIDMatch && userIDMatch[1]) {
          userID = userIDMatch[1].trim();
          console.log("找到用户ID:", userID);

          // 保存用户ID到全局变量，以便在各种函数中使用
          window.currentUserID = userID;
        }

        // 存储角色颜色映射
        const characterColors = {};

        if (liveMatch && liveMatch[1]) {
          // 获取<live>标记内的内容
          const liveContent = liveMatch[1].trim();
          // 按行分割
          const lines = liveContent.split("\n");

          // 如果有多个背景类型，则分割它们
          let backgroundTypes = [];
          if (backgroundInfo && backgroundInfo.includes("/")) {
            backgroundTypes = backgroundInfo.split("/").map((bg) => bg.trim());
          } else if (backgroundInfo) {
            backgroundTypes = [backgroundInfo];
          }

          let currentBgIndex = 0; // 用于轮换背景

          // 遍历每一行
          lines.forEach((line) => {
            // 跳过空行和标签行
            if (
              !line.trim() ||
              line.includes("<livebg>") ||
              line.includes("<livetitle>") ||
              line.includes("<userID>")
            )
              return;

            // 使用|分割角色名和内容
            const parts = line.split("|");
            if (parts.length >= 2) {
              const character = parts[0].trim();
              const content = parts.slice(1).join("|").trim();

              // 为角色分配颜色（如果尚未分配）
              if (!characterColors[character]) {
                // 生成随机颜色
                characterColors[character] = getRandomColor();
              }

              // 选择当前背景类型
              let currentBg = backgroundInfo;
              if (backgroundTypes.length > 0) {
                currentBg =
                  backgroundTypes[currentBgIndex % backgroundTypes.length];
                currentBgIndex++; // 移动到下一个背景
              }

              // 创建新的文本-图片对象
              newTextImagePairs.push({
                title: character,
                text: content,
                color: characterColors[character],
                backgroundInfo: currentBg,
                liveTitle: liveTitle,
              });
            }
          });

          // 如果成功解析了内容，则返回解析结果
          if (newTextImagePairs.length > 0) {
            console.log(
              `成功解析 ${newTextImagePairs.length} 行直播内容，直播间标题: ${liveTitle}`
            );
            return newTextImagePairs;
          }
        }

        return null; // 解析失败返回null
      }

      // 生成随机颜色的函数
      function getRandomColor() {
        // 生成较亮的颜色，适合在暗背景上显示
        const h = Math.floor(Math.random() * 360); // 色相
        const s = Math.floor(40 + Math.random() * 40); // 饱和度40%-80%
        const l = Math.floor(60 + Math.random() * 20); // 亮度60%-80%
        return `hsl(${h}, ${s}%, ${l}%)`;
      }

      // 解析<peek>标记的函数
      function parsePeekContent(contentStr) {
        const peekPattern = /<peek>([\s\S]*?)<\/peek>/;
        const peekMatch = contentStr.match(peekPattern);

        if (peekMatch && peekMatch[1]) {
          // 保留换行和空格格式
          const peekContent = peekMatch[1].trim();
          // 将换行符转换为<br>标签
          return peekContent.replace(/\n/g, "<br>");
        }

        return null;
      }

      // 解析<fan>标记的函数
      function parseFanContent(contentStr) {
        const fanPattern = /<fan>([\s\S]*?)<\/fan>/;
        const fanMatch = contentStr.match(fanPattern);

        if (fanMatch && fanMatch[1]) {
          // 保留换行和空格格式
          const fanContent = fanMatch[1].trim();
          // 将换行符转换为<br>标签
          return fanContent.replace(/\n/g, "<br>");
        }

        return null;
      }

      // 解析<streamer>标记的函数
      function parseStreamerContent(contentStr) {
        const streamerPattern = /<streamer>([\s\S]*?)<\/streamer>/;
        const streamerMatch = contentStr.match(streamerPattern);

        if (streamerMatch && streamerMatch[1]) {
          // 保留换行和空格格式
          const streamerContent = streamerMatch[1].trim();
          // 将换行符转换为<br>标签
          return streamerContent.replace(/\n/g, "<br>");
        }

        return null;
      }

      // 示例live内容字符串 - 注释中添加说明可以是任意行数
      /*
      * 直播内容格式：
      * <live>
      * <livebg>背景图片描述</livebg>
      * <livetitle>直播间标题</livetitle>
