      // 在script标签内添加弹幕池管理代码
      const danmakuPool = {
        // 固定弹幕内容
        fixedDanmaku: [
          {
            content: "可爱，单推，结婚",
            user: "DD是生活方式",
            isCustom: false,
          },
          { content: "开门开门", user: "首号gachi", isCustom: false },
          { content: "誰も大好き", user: "不DD不人生", isCustom: false },
          { content: "www", user: "樱岛里有麻衣", isCustom: false },
        ],
        // 自定义弹幕槽位（初始为空）
        customDanmaku: new Array(4).fill(null),
        // 当前弹幕索引
        currentIndex: 0,
        // 添加自定义弹幕
        addCustomDanmaku(content, user) {
          // 寻找一个空槽位
          const emptySlot = this.customDanmaku.findIndex(
            (slot) => slot === null
          );
          if (emptySlot !== -1) {
            this.customDanmaku[emptySlot] = { content, user, isCustom: true };
          } else {
            // 如果没有空槽位，替换最老的自定义弹幕
            this.customDanmaku.shift();
            this.customDanmaku.push({ content, user, isCustom: true });
          }
        },
        // 获取下一条弹幕
        getNextDanmaku() {
          // 合并固定和自定义弹幕
          const allDanmaku = [
            ...this.fixedDanmaku,
            ...this.customDanmaku.filter((d) => d !== null),
          ];

          const danmaku = allDanmaku[this.currentIndex];
          this.currentIndex = (this.currentIndex + 1) % allDanmaku.length;
          return danmaku;
        },
      };

