        };

        // 使用fetch API发送数据
        fetch('https://your-api-endpoint.com/danmaku', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(data)
        })
        .then(response => {
          if (!response.ok) {
            throw new Error('API请求失败');
          }
          return response.json();
        })
        .then(data => {
