        const userAvatar = document.querySelector(".user-avatar"); // 添加用户头像
        const userName = document.querySelector(".user-name"); // 添加用户名称
        const currentData = textImagePairs[textIndex];

        // 根据背景信息选择图片
        const backgroundImage = getBackgroundImage(currentData.backgroundInfo);

        // 更新livebg图片并显示容器
        if (backgroundImage) {
          livebgImg.src = backgroundImage;
          livebgContainer.classList.add("show");
        } else {
          livebgContainer.classList.remove("show");
