        // 默认图片
        let imageUrl = "https://files.catbox.moe/tku2eg.jpg";

        // 根据背景信息选择不同的图片
        if (backgroundInfo) {
          const lowerInfo = backgroundInfo.toLowerCase();

          // 根据关键词选择图片
          if (lowerInfo.includes("asmr")) {
            imageUrl = "https://files.catbox.moe/tku2eg.jpg"; // ASMR背景图
          } else if (lowerInfo.includes("联动")) {
            imageUrl = "https://files.catbox.moe/tku2eg.jpg"; // 联动背景图
          } else if (lowerInfo.includes("游戏")) {
            imageUrl = "https://files.catbox.moe/tku2eg.jpg"; // 游戏背景图
          } else if (lowerInfo.includes("视频鉴赏")) {
            imageUrl = "https://files.catbox.moe/tku2eg.jpg"; // 视频鉴赏背景图
          } else if (lowerInfo.includes("唱歌")) {
            imageUrl = "https://files.catbox.moe/tku2eg.jpg"; // 唱歌背景图
          } else {
            imageUrl = "https://files.catbox.moe/tku2eg.jpg"; // 默认背景图
