          const danmakuItem = document.createElement("div");
          danmakuItem.classList.add("danmaku-item");
          danmakuItem.classList.add("gift-danmaku");

          if (container.classList.contains("portrait-danmaku")) {
            danmakuItem.innerHTML = `<span class="danmaku-user">系统消息：</span><span class="danmaku-content">${content}</span>`;
          } else {
            danmakuItem.textContent = content;
            danmakuItem.style.top = `${Math.random() * 80}%`;
            danmakuItem.style.color = "yellow";
            danmakuItem.style.fontWeight = "bold";
          }

          container.appendChild(danmakuItem);

          setTimeout(() => {
            danmakuItem.remove();
          }, 10000);
        }

        // 更新礼物计数
        function updateGiftCount() {
          const giftCount = document.querySelector(".gift-count");
          if (giftCount) {
            // 获取当前计数
            let count = parseInt(giftCount.textContent) || 0;

            // 如果是带+号的文本格式
            if (giftCount.textContent.includes("+")) {
              count = parseInt(giftCount.textContent.replace("+", ""));
            }

            // 增加计数并更新
            count += 1;
            giftCount.textContent = count > 999 ? "999+" : count.toString();

            // 添加闪烁动画效果
            giftCount.style.animation = "none";
            void giftCount.offsetWidth; // 强制重排
            giftCount.style.animation = "pulse 0.5s";
          }
        }

        // 添加闪烁动画CSS
        const style = document.createElement("style");
        style.textContent = `
                @keyframes pulse {
                    0% { transform: scale(1); }
                    50% { transform: scale(1.2); }
                    100% { transform: scale(1); }
                }
            `;
        document.head.appendChild(style);
      });

      // 添加SC功能
      document.addEventListener("DOMContentLoaded", () => {
        const scButton = document.getElementById("sc-button");
        const scModal = document.getElementById("sc-modal");
        const closeScModal = document.getElementById("close-sc-modal");
        const scContent = document.getElementById("sc-content");
        const scPriceOptions = document.querySelectorAll(".sc-price-option");
        const scColorOptions = document.querySelectorAll(".sc-color-option");
        const scSendButton = document.getElementById("sc-send-button");
        const scMessagesContainer = document.getElementById(
          "sc-messages-container"
        );
        const systemOverlay = document.getElementById("system-overlay");

        let selectedPrice = null;
        let selectedColor = null;

        // 打开SC弹窗
        scButton.addEventListener("click", () => {
          // 显示系统遮罩
          systemOverlay.style.display = "block";
          setTimeout(() => {
            systemOverlay.classList.add("show");
          }, 10);

          // 显示SC弹窗
          scModal.style.display = "flex";
          void scModal.offsetWidth; // 强制重排
          scModal.classList.add("show");

          // 高亮SC按钮
          scButton.classList.add("active");
        });

        // 关闭SC弹窗
        closeScModal.addEventListener("click", () => {
          // 隐藏系统遮罩
          systemOverlay.classList.remove("show");

          // 隐藏SC弹窗
          scModal.classList.remove("show");

          // 等待动画完成后隐藏
          setTimeout(() => {
            scModal.style.display = "none";
            systemOverlay.style.display = "none";
          }, 300);

          // 移除SC按钮高亮
          scButton.classList.remove("active");
        });

        // 点击遮罩层也可以关闭SC弹窗
        systemOverlay.addEventListener("click", (e) => {
          if (
            e.target === systemOverlay &&
            scModal.classList.contains("show")
          ) {
            closeScModal.click();
          }
        });

        // 选择金额
        scPriceOptions.forEach((option) => {
          option.addEventListener("click", () => {
            // 移除其他金额的选中状态
            scPriceOptions.forEach((opt) => opt.classList.remove("selected"));

            // 添加当前金额的选中状态
            option.classList.add("selected");

            // 记录选中的金额
            selectedPrice = option.getAttribute("data-price");
          });
        });

        // 选择颜色
        scColorOptions.forEach((option) => {
          option.addEventListener("click", () => {
            // 移除其他颜色的选中状态
            scColorOptions.forEach((opt) => opt.classList.remove("selected"));

            // 添加当前颜色的选中状态
            option.classList.add("selected");

            // 记录选中的颜色
            selectedColor = option.getAttribute("data-color");

            // 预览效果 - 改变文本框颜色
            scContent.style.backgroundColor = hexToRgba(selectedColor, 0.2);
            scContent.style.borderColor = hexToRgba(selectedColor, 0.5);
          });
        });

        // 发送SC
        scSendButton.addEventListener("click", () => {
          const content = scContent.value.trim();

          if (!content) {
            alert("请输入SC内容");
            return;
          }

          if (!selectedPrice) {
            alert("请选择金额");
            return;
          }

          if (!selectedColor) {
            alert("请选择颜色");
            return;
          }

          // 关闭SC弹窗
          closeScModal.click();

          // 发送SC消息
          sendSuperChat(content, selectedPrice, selectedColor);

          // 重置表单
          scContent.value = "";
          scContent.style.backgroundColor = "";
          scContent.style.borderColor = "";
          scPriceOptions.forEach((opt) => opt.classList.remove("selected"));
          scColorOptions.forEach((opt) => opt.classList.remove("selected"));
          selectedPrice = null;
          selectedColor = null;
        });

        // 发送SuperChat消息
        function sendSuperChat(content, price, color) {
          // 使用解析的用户ID，如果未找到则使用默认值
          const userName = window.currentUserID || "user的大手";

          // 创建SC消息元素
          const scMessage = document.createElement("div");
          scMessage.classList.add("sc-message");
          scMessage.style.backgroundColor = hexToRgba(color, 0.8);
          scMessage.style.color = getContrastColor(color);
          scMessage.style.top = `${getRandomPosition()}px`;

          // 创建SC消息内容
          scMessage.innerHTML = `
                    <div class="sc-message-header">
                        <div class="sc-message-user">${userName}</div>
                        <div class="sc-message-price">¥${price}</div>
                    </div>
                    <div class="sc-message-content">${content}</div>
                `;

          // 添加到SC消息容器
          scMessagesContainer.appendChild(scMessage);

          // 10秒后移除SC消息
          setTimeout(() => {
            scMessage.remove();
          }, 10000);

          // 播放提示音
          playScSound();

          // 发送SC弹幕
          addScDanmaku(content, price, color);

          // 与SillyTavern集成：使用全局函数发送SC信息
          try {
            window.sendToSillyTavern(`【直播醒目留言】${userName} 发送了 ¥${price} SC：${content}`);
            console.log('已向SillyTavern发送SC信息');
          } catch (error) {
            console.error('向SillyTavern发送SC信息失败:', error);
          }
        }

        // 添加SC弹幕
        function addScDanmaku(content, price, color) {
          // 使用解析的用户ID，如果未找到则使用默认值
          const userName = window.currentUserID || "user的大手";

          const container = document.querySelector(
            document
              .querySelector(".iphone-container")
              .classList.contains("landscape")
              ? ".landscape-danmaku"
              : ".portrait-danmaku"
          );

          const danmakuItem = document.createElement("div");
          danmakuItem.classList.add("danmaku-item");
          danmakuItem.style.background = `linear-gradient(90deg, ${hexToRgba(
            color,
            0.6
          )}, ${hexToRgba(color, 0.8)})`;
          danmakuItem.style.border = `1px solid ${hexToRgba(color, 0.9)}`;
          danmakuItem.style.boxShadow = `0 0 10px ${hexToRgba(color, 0.5)}`;

          if (container.classList.contains("portrait-danmaku")) {
            danmakuItem.innerHTML = `<span class="danmaku-user" style="color: yellow;">${userName} (¥${price})：</span><span class="danmaku-content">${content}</span>`;
          } else {
            danmakuItem.textContent = `${userName} (¥${price}): ${content}`;
            danmakuItem.style.top = `${Math.random() * 80}%`;
            danmakuItem.style.color = getContrastColor(color);
            danmakuItem.style.fontWeight = "bold";
          }

          container.appendChild(danmakuItem);

          setTimeout(() => {
            danmakuItem.remove();
          }, 10000);
        }

        // 获取随机位置
        function getRandomPosition() {
          // 计算手机屏幕上半部分的随机位置
          const phoneHeight = document
            .querySelector(".iphone-frame")
            .getBoundingClientRect().height;
          return 50 + Math.random() * (phoneHeight / 2 - 100); // 上半部分随机位置
        }

        // 播放SC提示音
        function playScSound() {
          const audioContext = new (window.AudioContext ||
            window.webkitAudioContext)();
          const oscillator = audioContext.createOscillator();
          const gainNode = audioContext.createGain();

          oscillator.type = "sine";
          oscillator.frequency.setValueAtTime(880, audioContext.currentTime); // A5
          oscillator.frequency.exponentialRampToValueAtTime(
            440,
            audioContext.currentTime + 0.2
          ); // A4

          gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
          gainNode.gain.exponentialRampToValueAtTime(
            0.01,
            audioContext.currentTime + 0.5
          );

          oscillator.connect(gainNode);
          gainNode.connect(audioContext.destination);

          oscillator.start();
          oscillator.stop(audioContext.currentTime + 0.5);
        }

        // 颜色工具函数
        function hexToRgba(hex, alpha = 1) {
          const r = parseInt(hex.slice(1, 3), 16);
          const g = parseInt(hex.slice(3, 5), 16);
          const b = parseInt(hex.slice(5, 7), 16);
          return `rgba(${r}, ${g}, ${b}, ${alpha})`;
        }

        function getContrastColor(hexColor) {
          const r = parseInt(hexColor.slice(1, 3), 16);
          const g = parseInt(hexColor.slice(3, 5), 16);
          const b = parseInt(hexColor.slice(5, 7), 16);

          // 计算亮度 (ITU-R BT.709)
          const luminance = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;

          // 返回黑色或白色作为对比色
          return luminance > 0.5 ? "#000000" : "#FFFFFF";
        }

        // 默认选中第一个价格和颜色选项
        if (scPriceOptions.length > 0) {
          scPriceOptions[0].click();
        }

        if (scColorOptions.length > 0) {
          scColorOptions[0].click();
        }
      });
    </script>
  </body>
</html>
