    <script>
      // 添加旋转功能开关变量
      let rotationEnabled = true; // 设为false可禁用旋转功能

      // 创建背景图片数组
      const backgroundImages = [
        "https://files.catbox.moe/tku2eg.jpg",
        "https://files.catbox.moe/tku2eg.png",
        // 以下是为不同直播类型增加的图片
        "https://files.catbox.moe/tku2eg.jpg", // ASMR背景
        "https://files.catbox.moe/tku2eg.png", // 联动背景
        "https://files.catbox.moe/tku2eg.jpg", // 游戏背景
        "https://files.catbox.moe/tku2eg.png", // 视频鉴赏背景
        "https://files.catbox.moe/tku2eg.jpg", // 唱歌背景
        // 可以添加更多图片URL
      ];

      // 随机选择背景图片
      function randomizeBackground() {
        const randomIndex = Math.floor(Math.random() * backgroundImages.length);
        const selectedImage = backgroundImages[randomIndex];

        // 更新横屏模式的背景图片
        document.querySelector(".landscape-content img").src = selectedImage;

        // 更新livebg图片
        const livebgImg = document.querySelector(".livebg-image");
        if (livebgImg) {
          livebgImg.src = selectedImage;
          document.querySelector(".livebg-container").classList.add("show");
        }
      }

      // 添加与文本对应的图片数组
      const textImagePairs = [
        {
          text: "在这里显示文本内容",
          //   image: "https://files.catbox.moe/0bv8nc.jpg",
        },
        {
          text: "第二段文本内容示例，第二段文本内容示例。第二段文本内容示例，第二段文本内容示例。",
          //   image: "https://files.catbox.moe/8bdvbd.png",
        },
        {
          text: "第三段文本内容示例",
          //   image: "https://files.catbox.moe/0bv8nc.jpg",
        },
        {
          text: "第四段文本内容示例",
          //   image: "https://files.catbox.moe/8bdvbd.png",
        },
      ];

      // 解析<live>标记的函数
      function parseLiveContent(liveContentStr) {
        // 创建新的文本-图片对数组
        const newTextImagePairs = [];

        // 使用正则表达式解析<live>标记内的内容
        const livePattern = /<live>([\s\S]*?)<\/live>/;
        const liveMatch = liveContentStr.match(livePattern);

        // 解析背景图片标签
        let backgroundInfo = null;
        const bgPattern = /<livebg>([\s\S]*?)<\/livebg>/;
        const bgMatch = liveContentStr.match(bgPattern);
        if (bgMatch && bgMatch[1]) {
          backgroundInfo = bgMatch[1].trim();
        }

        // 解析直播间标题
        let liveTitle = null;
        const titlePattern = /<livetitle>([\s\S]*?)<\/livetitle>/;
        const titleMatch = liveContentStr.match(titlePattern);
        if (titleMatch && titleMatch[1]) {
          liveTitle = titleMatch[1].trim();
          console.log("找到直播间标题:", liveTitle); // 添加调试输出

          // 立即更新DOM中的直播间标题
          document.addEventListener("DOMContentLoaded", () => {
            const userNameElement = document.querySelector(".user-name");
            if (userNameElement) {
              userNameElement.textContent = liveTitle;
              console.log("DOMContentLoaded: 直播间标题已设置为", liveTitle);
            }
          });

          // 如果DOM已经加载完成，则立即设置
          if (
            document.readyState === "complete" ||
            document.readyState === "interactive"
          ) {
            const userNameElement = document.querySelector(".user-name");
            if (userNameElement) {
              userNameElement.textContent = liveTitle;
              console.log("立即设置: 直播间标题已设置为", liveTitle);
            }
          }
        }

        // 提取用户ID
        let userID = "user的大手"; // 默认用户名
        const userIDPattern = /<userID>([\s\S]*?)<\/userID>/;
        const userIDMatch = liveContentStr.match(userIDPattern);
        if (userIDMatch && userIDMatch[1]) {
          userID = userIDMatch[1].trim();
          console.log("找到用户ID:", userID);

          // 保存用户ID到全局变量，以便在各种函数中使用
          window.currentUserID = userID;
        }

        // 存储角色颜色映射
        const characterColors = {};

        if (liveMatch && liveMatch[1]) {
          // 获取<live>标记内的内容
          const liveContent = liveMatch[1].trim();
          // 按行分割
          const lines = liveContent.split("\n");

          // 如果有多个背景类型，则分割它们
          let backgroundTypes = [];
          if (backgroundInfo && backgroundInfo.includes("/")) {
            backgroundTypes = backgroundInfo.split("/").map((bg) => bg.trim());
          } else if (backgroundInfo) {
            backgroundTypes = [backgroundInfo];
          }

          let currentBgIndex = 0; // 用于轮换背景

          // 遍历每一行
          lines.forEach((line) => {
            // 跳过空行和标签行
            if (
              !line.trim() ||
              line.includes("<livebg>") ||
              line.includes("<livetitle>") ||
              line.includes("<userID>")
            )
              return;

            // 使用|分割角色名和内容
            const parts = line.split("|");
            if (parts.length >= 2) {
              const character = parts[0].trim();
              const content = parts.slice(1).join("|").trim();

              // 为角色分配颜色（如果尚未分配）
              if (!characterColors[character]) {
                // 生成随机颜色
                characterColors[character] = getRandomColor();
              }

              // 选择当前背景类型
              let currentBg = backgroundInfo;
              if (backgroundTypes.length > 0) {
                currentBg =
                  backgroundTypes[currentBgIndex % backgroundTypes.length];
                currentBgIndex++; // 移动到下一个背景
              }

              // 创建新的文本-图片对象
              newTextImagePairs.push({
                title: character,
                text: content,
                color: characterColors[character],
                backgroundInfo: currentBg,
                liveTitle: liveTitle,
              });
            }
          });

          // 如果成功解析了内容，则返回解析结果
          if (newTextImagePairs.length > 0) {
            console.log(
              `成功解析 ${newTextImagePairs.length} 行直播内容，直播间标题: ${liveTitle}`
            );
            return newTextImagePairs;
          }
        }

        return null; // 解析失败返回null
      }

      // 生成随机颜色的函数
      function getRandomColor() {
        // 生成较亮的颜色，适合在暗背景上显示
        const h = Math.floor(Math.random() * 360); // 色相
        const s = Math.floor(40 + Math.random() * 40); // 饱和度40%-80%
        const l = Math.floor(60 + Math.random() * 20); // 亮度60%-80%
        return `hsl(${h}, ${s}%, ${l}%)`;
      }

      // 解析<peek>标记的函数
      function parsePeekContent(contentStr) {
        const peekPattern = /<peek>([\s\S]*?)<\/peek>/;
        const peekMatch = contentStr.match(peekPattern);

        if (peekMatch && peekMatch[1]) {
          // 保留换行和空格格式
          const peekContent = peekMatch[1].trim();
          // 将换行符转换为<br>标签
          return peekContent.replace(/\n/g, "<br>");
        }

        return null;
      }

      // 解析<fan>标记的函数
      function parseFanContent(contentStr) {
        const fanPattern = /<fan>([\s\S]*?)<\/fan>/;
        const fanMatch = contentStr.match(fanPattern);

        if (fanMatch && fanMatch[1]) {
          // 保留换行和空格格式
          const fanContent = fanMatch[1].trim();
          // 将换行符转换为<br>标签
          return fanContent.replace(/\n/g, "<br>");
        }

        return null;
      }

      // 解析<streamer>标记的函数
      function parseStreamerContent(contentStr) {
        const streamerPattern = /<streamer>([\s\S]*?)<\/streamer>/;
        const streamerMatch = contentStr.match(streamerPattern);

        if (streamerMatch && streamerMatch[1]) {
          // 保留换行和空格格式
          const streamerContent = streamerMatch[1].trim();
          // 将换行符转换为<br>标签
          return streamerContent.replace(/\n/g, "<br>");
        }

        return null;
      }

      // 示例live内容字符串 - 注释中添加说明可以是任意行数
      /*
      * 直播内容格式：
      * <live>
      * <livebg>背景图片描述</livebg>
      * <livetitle>直播间标题</livetitle>
      * 角色名|对话内容
      * 角色名|对话内容
      * ...可以添加任意数量的行
      * </live>
      * <peek>中之人视角内容</peek>
      * <fan>粉丝视角内容</fan>
      * <streamer>主播视角内容</streamer>
      */
      const liveContentExample = `$1`;

      // 先解析并处理所有内容（包括剧情弹幕）
      const processedContent = parseAllContent(liveContentExample);

      // 解析示例内容并替换textImagePairs
      const parsedContent = parseLiveContent(processedContent);
      if (parsedContent) {
        // 替换原有的textImagePairs
        textImagePairs.length = 0; // 清空原数组
        parsedContent.forEach((item) => textImagePairs.push(item)); // 添加新内容
        console.log(`初始化了 ${textImagePairs.length} 条直播内容`);
      }

      // 解析peek内容并更新系统内容区域
      const peekContent = parsePeekContent(liveContentExample);
      if (peekContent) {
        // 在DOM加载完成后设置内容
        document.addEventListener("DOMContentLoaded", () => {
          const systemContent = document.querySelector(".system-content");
          if (systemContent) {
            // 添加当前时间戳显示
            const now = new Date();
            const hours = String(now.getHours()).padStart(2, "0");
            const minutes = String(now.getMinutes()).padStart(2, "0");
            const seconds = String(now.getSeconds()).padStart(2, "0");
            const timeString = `${hours}:${minutes}:${seconds}`;

            // 使用新样式展示peek内容
            systemContent.innerHTML = `
                    <div class="peek-content">
                        <div class="peek-live-indicator"></div>
                        <div style="width: 100%;">${peekContent}</div>
                    </div>
                    <p style="text-align: center; margin-top: 10px; opacity: 0.7;">
                        录制中 • 时间戳: ${timeString} • 未公开信号
                    </p>`;

            // 设置一个定时器定期更新时间戳
            setInterval(() => {
              const now = new Date();
              const hours = String(now.getHours()).padStart(2, "0");
              const minutes = String(now.getMinutes()).padStart(2, "0");
              const seconds = String(now.getSeconds()).padStart(2, "0");
              const timeString = `${hours}:${minutes}:${seconds}`;

              const timeStampElement = systemContent.querySelector("p");
              if (timeStampElement) {
                timeStampElement.innerHTML = `录制中 • 时间戳: ${timeString} • 未公开信号`;
              }
            }, 1000);
          }
        });
      }

      // 解析fan内容并更新粉丝视角内容区域
      const fanContent = parseFanContent(liveContentExample);
      if (fanContent) {
        // 在DOM加载完成后设置内容
        document.addEventListener("DOMContentLoaded", () => {
          const fanPerspective = document.querySelector(".fan-perspective");
          if (fanPerspective) {
            // 设置粉丝视角内容
            fanPerspective.innerHTML = `<div style="width: 100%;">${fanContent}</div>`;
          }
        });
      }

      // 解析streamer内容并更新主播视角内容区域
      const streamerContent = parseStreamerContent(liveContentExample);
      if (streamerContent) {
        // 在DOM加载完成后设置内容
        document.addEventListener("DOMContentLoaded", () => {
          const streamerPerspective = document.querySelector(
            ".streamer-perspective"
          );
          if (streamerPerspective) {
            // 设置主播视角内容
            streamerPerspective.innerHTML = `<div style="width: 100%;">${streamerContent}</div>`;
          }
        });
      }

      let currentScale = 1;
      const slider = document.querySelector(".scale-slider");
      const scaleValue = document.querySelector(".scale-value");

      // 限制快速更新的函数
      function debounce(func, wait) {
        let timeout;
        return function executedFunction(...args) {
          const later = () => {
            clearTimeout(timeout);
            func(...args);
          };
          clearTimeout(timeout);
          timeout = setTimeout(later, wait);
        };
      }

      // 更新缩放比例函数
      function updateScale(value) {
        const scale = value / 100;
        currentScale = scale;
        const container = document.querySelector(".iphone-container");
        const isLandscape = container.classList.contains("landscape");

        if (isLandscape && rotationEnabled) {
          // 如果旋转功能启用，则应用旋转
          container.style.transform = `rotate(-90deg) scale(${scale})`;
        } else {
          container.style.transform = `scale(${scale})`;
        }
        scaleValue.textContent = `${value}%`;
      }

      // 添加滑块事件监听
      slider.addEventListener(
        "input",
        debounce((e) => {
          updateScale(e.target.value);
        }, 10)
      );

      // 简化后的旋转函数
      function toggleRotation() {
        const container = document.querySelector(".iphone-container");
        //const portraitContent = document.querySelector('.phone-content');
        const landscapeContent = document.querySelector(".landscape-content");
        const livebgContainer = document.querySelector(".livebg-container"); // 添加livebg容器
        const isLandscape = container.classList.contains("landscape");

        // 切换横竖屏状态
        container.classList.toggle("landscape");

        if (!isLandscape) {
          // 切换到横屏
          //portraitContent.style.opacity = '0';
          setTimeout(() => {
            //portraitContent.style.display = 'none';
            landscapeContent.style.display = "flex";
            // 强制重排
            void landscapeContent.offsetWidth;
            landscapeContent.style.opacity = "1";
          }, 300);
        } else {
          // 切换到竖屏
          landscapeContent.style.opacity = "0";
          setTimeout(() => {
            landscapeContent.style.display = "none";
            //portraitContent.style.display = 'flex';
            // 强制重排
            //void portraitContent.offsetWidth;
            //portraitContent.style.opacity = '1';
          }, 300);
        }

        // 更新缩放
        updateScale(slider.value);
      }

      // 添加实时时间更新函数
      function updateTime() {
        const timeElement = document.querySelector(".live-time");
        const now = new Date();
        const hours = String(now.getHours()).padStart(2, "0");
        const minutes = String(now.getMinutes()).padStart(2, "0");
        timeElement.textContent = `${hours}:${minutes}`;
      }

      // 初始化
      document.addEventListener("DOMContentLoaded", () => {
        randomizeBackground(); // 随机设置背景图片
        updateScale(100);
        updateTime(); // 初始化时间
        setInterval(updateTime, 60000); // 每分钟更新一次

        // 添加剧情弹幕的定时显示功能
        setInterval(() => {
          const scriptedDanmaku = scriptedDanmakuPool.getNextDanmaku();
          if (scriptedDanmaku) {
            addDanmaku(scriptedDanmaku.content, scriptedDanmaku.user, false, true); // 最后一个参数标记为剧情弹幕
          }
        }, 4000); // 每4秒显示一条剧情弹幕

        // 历史记录按钮点击事件
        const openNoteButton = document.getElementById("open-note-button");
