          danmakuItem.classList.add("custom-danmaku");
        } else if (isScripted) {
          danmakuItem.classList.add("scripted-danmaku"); // 添加剧情弹幕特有的样式
        }

        // 使用传入的参数，不再调用getNextDanmaku()
        if (container.classList.contains("portrait-danmaku")) {
          danmakuItem.innerHTML = `<span class="danmaku-user ${
            isCustom ? "custom-user" : ""
          }">${user}：</span><span class="danmaku-content">${content}</span>`;
        } else {
          danmakuItem.textContent = content;
          danmakuItem.style.top = `${Math.random() * 80}%`;

          if (isCustom) {
            danmakuItem.style.color = "#FF69B4";
            danmakuItem.style.fontWeight = "bold";
