      // 调用时传入第三个参数
      setTimeout(() => {
        setInterval(() => {
          const danmaku = danmakuPool.getNextDanmaku();
          if (danmaku) {
            addDanmaku(danmaku.content, danmaku.user, danmaku.isCustom);
          }
        }, 4000);
      }, 2000);

      // 发送弹幕内容到外部API的函数
      function sendDanmakuToAPI(content, userName) {
        // 构建请求数据
        const data = {
          content: content,
          user: userName,
          timestamp: new Date().toISOString()
        };

        // 使用fetch API发送数据
        fetch('https://your-api-endpoint.com/danmaku', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(data)
        })
        .then(response => {
          if (!response.ok) {
            throw new Error('API请求失败');
          }
          return response.json();
        })
        .then(data => {
          console.log('API响应:', data);
        })
        .catch(error => {
          console.error('发送弹幕到API时出错:', error);
        });
      }

