        }

        // 更新头像
        if (userAvatar) {
          userAvatar.src = "https://files.catbox.moe/6ff1mv.png"; // 默认头像
        }

        // 清空当前文本内容
        textElement.textContent = "";
        landscapeTextElement.textContent = "";

        // 更新标题元素 - 当直播间标题存在时修改内容为角色名
        if (currentData.title) {
          // 修改为角色名
          titleElement.textContent = `${currentData.title}:`;
          landscapeTitleElement.textContent = `${currentData.title}:`;

          // 设置标题颜色
          if (currentData.color) {
            titleElement.style.color = currentData.color;
            landscapeTitleElement.style.color = currentData.color;
            // 添加文字阴影以增强可读性
            titleElement.style.textShadow = "0px 0px 2px rgba(0, 0, 0, 0.8)";
            landscapeTitleElement.style.textShadow =
              "0px 0px 2px rgba(0, 0, 0, 0.8)";
          } else {
            // 重置样式
            titleElement.style.color = "";
            landscapeTitleElement.style.color = "";
            titleElement.style.textShadow = "";
            landscapeTitleElement.style.textShadow = "";
          }
        }

        // 清除所有未完成的动画
        currentTypingTimeouts.forEach((timeout) => clearTimeout(timeout));
        currentTypingTimeouts = []; // 重置数组

        // 逐字显示文本动画
        let charIndex = 0;
        function typeNextChar() {
          if (charIndex < currentData.text.length) {
            textElement.textContent += currentData.text[charIndex];
            landscapeTextElement.textContent += currentData.text[charIndex];
            charIndex++;
            const timeout = setTimeout(typeNextChar, 50); // 每个字符间隔 50ms
            currentTypingTimeouts.push(timeout); // 保存 timeout 标识符
          }
        }
        typeNextChar();
      }

