              systemOverlay.style.display = "none";
            }, 300);
          });
        }

        // 点击遮罩层也可以关闭粉丝视角框
        systemOverlay.addEventListener("click", (e) => {
          if (
            e.target === systemOverlay &&
            fanFullscreenBox.classList.contains("show")
          ) {
            closeFanBox.click();
          }
        });

        // 随机更新粉丝热度数值
        function updateFanHeatCount() {
          const heatCountElement = document.querySelector(".fan-content p");
          if (heatCountElement) {
            const randomHeat = Math.floor(900 + Math.random() * 300);
            heatCountElement.innerHTML = `实时粉丝情绪分析 • 热度${randomHeat}+`;
          }
          setTimeout(updateFanHeatCount, 3000 + Math.random() * 2000);
        }
        updateFanHeatCount();
      });

      // 添加中之人视角文本框样式和HTML元素，并绑定在导航栏左侧用户头像上
      document.addEventListener("DOMContentLoaded", () => {
        const userAvatar = document.querySelector(".user-avatar");
        const streamerFullscreenBox = document.getElementById(
          "streamer-fullscreen-box"
        );
        const closeStreamerBox = document.getElementById("close-streamer-box");
        const systemOverlay = document.getElementById("system-overlay");

        if (userAvatar) {
          userAvatar.addEventListener("click", () => {
            // 显示遮罩层
            systemOverlay.style.display = "block";
            setTimeout(() => {
              systemOverlay.classList.add("show");
            }, 10);

            // 先显示系统框但设置为透明
            streamerFullscreenBox.style.display = "flex";
            // 强制重排
            void streamerFullscreenBox.offsetWidth;
            // 添加显示类触发动画
            streamerFullscreenBox.classList.add("show");
          });
        }

        if (closeStreamerBox) {
          closeStreamerBox.addEventListener("click", () => {
            // 隐藏遮罩层
            systemOverlay.classList.remove("show");

            // 添加隐藏类触发收缩动画
            streamerFullscreenBox.classList.add("hide");
            streamerFullscreenBox.classList.remove("show");

            // 等待动画完成后隐藏
            setTimeout(() => {
              streamerFullscreenBox.style.display = "none";
              streamerFullscreenBox.classList.remove("hide");
              systemOverlay.style.display = "none";
            }, 300);
          });
        }

        // 点击遮罩层也可以关闭中之人视角框
        systemOverlay.addEventListener("click", (e) => {
          if (
            e.target === systemOverlay &&
            streamerFullscreenBox.classList.contains("show")
          ) {
            closeStreamerBox.click();
          }
        });

        // 随机更新中之人热度数值
        function updateStreamerHeatCount() {
          const heatCountElement = document.querySelector(
            ".streamer-content p"
          );
          if (heatCountElement) {
            const randomHeat = Math.floor(900 + Math.random() * 300);
            heatCountElement.innerHTML = `实时中之人视角 • 热度${randomHeat}+`;
          }
          setTimeout(updateStreamerHeatCount, 3000 + Math.random() * 2000);
        }
        updateStreamerHeatCount();
      });

      // 添加背景选择功能
      document.addEventListener("DOMContentLoaded", () => {
        const bgSelectButton = document.getElementById("bg-select-button");
        const bgSelectModal = document.getElementById("bg-select-modal");
        const closeBgModal = document.getElementById("close-bg-modal");
        const bgOptions = document.querySelectorAll(
          ".bg-option:not(.bg-option-upload)"
        );
        const bgUpload = document.getElementById("bg-upload");
        const systemOverlay = document.getElementById("system-overlay");

        // 打开背景选择弹窗
        bgSelectButton.addEventListener("click", () => {
          // 显示系统遮罩
          systemOverlay.style.display = "block";
          setTimeout(() => {
            systemOverlay.classList.add("show");
          }, 10);

          // 显示背景选择弹窗
          bgSelectModal.style.display = "flex";
          void bgSelectModal.offsetWidth; // 强制重排
          bgSelectModal.classList.add("show");
        });

        // 关闭背景选择弹窗
        closeBgModal.addEventListener("click", () => {
          // 隐藏系统遮罩
          systemOverlay.classList.remove("show");

          // 隐藏背景选择弹窗
          bgSelectModal.classList.remove("show");

          // 等待动画完成后隐藏
          setTimeout(() => {
            bgSelectModal.style.display = "none";
            systemOverlay.style.display = "none";
          }, 300);
        });

        // 点击遮罩层也可以关闭背景选择弹窗
        systemOverlay.addEventListener("click", (e) => {
          if (
            e.target === systemOverlay &&
            bgSelectModal.classList.contains("show")
          ) {
            closeBgModal.click();
          }
        });

        // 选择预设背景
        bgOptions.forEach((option) => {
          option.addEventListener("click", () => {
            const bgUrl = option.getAttribute("data-bg-url");
            changeBackground(bgUrl);
            closeBgModal.click(); // 关闭弹窗
          });
        });

        // 上传自定义背景
        bgUpload.addEventListener("change", (e) => {
          const file = e.target.files[0];
          if (file) {
            const reader = new FileReader();
            reader.onload = function (event) {
              const imgUrl = event.target.result;
              changeBackground(imgUrl);
              closeBgModal.click(); // 关闭弹窗
            };
            reader.readAsDataURL(file);
          }
        });

        // 更改背景函数
        function changeBackground(url) {
          // 更新livebg图片
          const livebgImg = document.querySelector(".livebg-image");
          if (livebgImg) {
            livebgImg.src = url;
            document.querySelector(".livebg-container").classList.add("show");
          }

          // 同时更新横屏背景（作为备用）
          const landscapeImg = document.querySelector(".landscape-content img");
          if (landscapeImg) landscapeImg.src = url;

          // 保存到本地存储以便下次访问时使用
          localStorage.setItem("customBackground", url);
        }

        // 检查是否有保存的自定义背景
        const savedBg = localStorage.getItem("customBackground");
        if (savedBg) {
          changeBackground(savedBg);
        }
      });

      // 添加礼物功能
      document.addEventListener("DOMContentLoaded", () => {
        const giftButton = document.getElementById("gift-button");
        const giftModal = document.getElementById("gift-modal");
        const closeGiftModal = document.getElementById("close-gift-modal");
        const giftItems = document.querySelectorAll(".gift-item");
        const giftSendButton = document.getElementById("gift-send-button");
        const giftEffect = document.getElementById("gift-effect");
        const giftAnimationIcon = document.querySelector(
          ".gift-animation-icon"
        );
        const giftAnimationText = document.querySelector(
          ".gift-animation-text"
        );
        const systemOverlay = document.getElementById("system-overlay");

        let selectedGift = null;

        // 打开礼物弹窗
        giftButton.addEventListener("click", () => {
          // 显示系统遮罩
          systemOverlay.style.display = "block";
          setTimeout(() => {
            systemOverlay.classList.add("show");
          }, 10);

          // 显示礼物弹窗
          giftModal.style.display = "flex";
          void giftModal.offsetWidth; // 强制重排
          giftModal.classList.add("show");

          // 高亮礼物按钮
          giftButton.classList.add("active");
        });

        // 关闭礼物弹窗
        closeGiftModal.addEventListener("click", () => {
          // 隐藏系统遮罩
          systemOverlay.classList.remove("show");

          // 隐藏礼物弹窗
          giftModal.classList.remove("show");

          // 等待动画完成后隐藏
          setTimeout(() => {
            giftModal.style.display = "none";
            systemOverlay.style.display = "none";
          }, 300);

          // 移除礼物按钮高亮
          giftButton.classList.remove("active");
        });

        // 点击遮罩层也可以关闭礼物弹窗
        systemOverlay.addEventListener("click", (e) => {
          if (
            e.target === systemOverlay &&
            giftModal.classList.contains("show")
          ) {
            closeGiftModal.click();
          }
        });

        // 选择礼物
        giftItems.forEach((item) => {
          item.addEventListener("click", () => {
            // 移除其他礼物的选中状态
            giftItems.forEach((i) => i.classList.remove("selected"));

            // 添加当前礼物的选中状态
            item.classList.add("selected");

            // 记录选中的礼物
            selectedGift = {
              icon: item.getAttribute("data-gift"),
              name: item.getAttribute("data-name"),
              price: item.getAttribute("data-price"),
            };
          });
        });

        // 赠送礼物
        giftSendButton.addEventListener("click", () => {
          if (!selectedGift) {
            alert("请先选择一个礼物");
            return;
          }

          // 使用解析的用户ID，如果未找到则使用默认值
          const userName = window.currentUserID || "user的大手";

          // 关闭礼物弹窗
          closeGiftModal.click();

          // 显示礼物特效
          giftAnimationIcon.textContent = selectedGift.icon;
          giftAnimationText.textContent = `${userName}赠送了${selectedGift.name}`;

          giftEffect.style.display = "flex";
          void giftEffect.offsetWidth; // 强制重排
          giftEffect.classList.add("show");

          // 3秒后隐藏特效
          setTimeout(() => {
            giftEffect.classList.remove("show");
            setTimeout(() => {
              giftEffect.style.display = "none";
            }, 500);
          }, 3000);

          // 发送礼物弹幕
          const giftDanmaku = `${userName}赠送了${selectedGift.name} x1 (${selectedGift.price}币)`;
          addGiftDanmaku(giftDanmaku);

          // 与SillyTavern集成：使用全局函数发送礼物信息
          try {
            window.sendToSillyTavern(`【直播礼物】${userName} 赠送了 ${selectedGift.name} x1 (${selectedGift.price}币)`);
            console.log('已向SillyTavern发送礼物信息');
          } catch (error) {
            console.error('向SillyTavern发送礼物信息失败:', error);
          }

          // 更新礼物计数
          updateGiftCount();

          // 重置选中的礼物
          selectedGift = null;
          giftItems.forEach((i) => i.classList.remove("selected"));
        });

        // 添加礼物弹幕
        function addGiftDanmaku(content) {
          const container = document.querySelector(
            document
              .querySelector(".iphone-container")
              .classList.contains("landscape")
              ? ".landscape-danmaku"
              : ".portrait-danmaku"
          );

          const danmakuItem = document.createElement("div");
          danmakuItem.classList.add("danmaku-item");
          danmakuItem.classList.add("gift-danmaku");

          if (container.classList.contains("portrait-danmaku")) {
            danmakuItem.innerHTML = `<span class="danmaku-user">系统消息：</span><span class="danmaku-content">${content}</span>`;
          } else {
            danmakuItem.textContent = content;
            danmakuItem.style.top = `${Math.random() * 80}%`;
            danmakuItem.style.color = "yellow";
            danmakuItem.style.fontWeight = "bold";
          }

          container.appendChild(danmakuItem);

          setTimeout(() => {
            danmakuItem.remove();
          }, 10000);
        }

        // 更新礼物计数
        function updateGiftCount() {
          const giftCount = document.querySelector(".gift-count");
          if (giftCount) {
            // 获取当前计数
            let count = parseInt(giftCount.textContent) || 0;

            // 如果是带+号的文本格式
            if (giftCount.textContent.includes("+")) {
              count = parseInt(giftCount.textContent.replace("+", ""));
            }

            // 增加计数并更新
            count += 1;
            giftCount.textContent = count > 999 ? "999+" : count.toString();

            // 添加闪烁动画效果
            giftCount.style.animation = "none";
            void giftCount.offsetWidth; // 强制重排
            giftCount.style.animation = "pulse 0.5s";
          }
        }

        // 添加闪烁动画CSS
        const style = document.createElement("style");
        style.textContent = `
                @keyframes pulse {
                    0% { transform: scale(1); }
                    50% { transform: scale(1.2); }
                    100% { transform: scale(1); }
                }
            `;
        document.head.appendChild(style);
      });

      // 添加SC功能
      document.addEventListener("DOMContentLoaded", () => {
        const scButton = document.getElementById("sc-button");
        const scModal = document.getElementById("sc-modal");
        const closeScModal = document.getElementById("close-sc-modal");
        const scContent = document.getElementById("sc-content");
        const scPriceOptions = document.querySelectorAll(".sc-price-option");
        const scColorOptions = document.querySelectorAll(".sc-color-option");
        const scSendButton = document.getElementById("sc-send-button");
        const scMessagesContainer = document.getElementById(
          "sc-messages-container"
        );
        const systemOverlay = document.getElementById("system-overlay");

        let selectedPrice = null;
        let selectedColor = null;

        // 打开SC弹窗
        scButton.addEventListener("click", () => {
          // 显示系统遮罩
          systemOverlay.style.display = "block";
          setTimeout(() => {
            systemOverlay.classList.add("show");
          }, 10);

          // 显示SC弹窗
          scModal.style.display = "flex";
          void scModal.offsetWidth; // 强制重排
          scModal.classList.add("show");

          // 高亮SC按钮
          scButton.classList.add("active");
        });

        // 关闭SC弹窗
        closeScModal.addEventListener("click", () => {
          // 隐藏系统遮罩
          systemOverlay.classList.remove("show");

          // 隐藏SC弹窗
          scModal.classList.remove("show");

          // 等待动画完成后隐藏
          setTimeout(() => {
            scModal.style.display = "none";
            systemOverlay.style.display = "none";
          }, 300);

          // 移除SC按钮高亮
          scButton.classList.remove("active");
        });

        // 点击遮罩层也可以关闭SC弹窗
        systemOverlay.addEventListener("click", (e) => {
          if (
            e.target === systemOverlay &&
            scModal.classList.contains("show")
          ) {
            closeScModal.click();
          }
        });

        // 选择金额
        scPriceOptions.forEach((option) => {
          option.addEventListener("click", () => {
            // 移除其他金额的选中状态
            scPriceOptions.forEach((opt) => opt.classList.remove("selected"));

            // 添加当前金额的选中状态
            option.classList.add("selected");

            // 记录选中的金额
            selectedPrice = option.getAttribute("data-price");
          });
        });

        // 选择颜色
        scColorOptions.forEach((option) => {
          option.addEventListener("click", () => {
            // 移除其他颜色的选中状态
            scColorOptions.forEach((opt) => opt.classList.remove("selected"));

            // 添加当前颜色的选中状态
            option.classList.add("selected");

            // 记录选中的颜色
            selectedColor = option.getAttribute("data-color");

            // 预览效果 - 改变文本框颜色
            scContent.style.backgroundColor = hexToRgba(selectedColor, 0.2);
            scContent.style.borderColor = hexToRgba(selectedColor, 0.5);
          });
        });

        // 发送SC
        scSendButton.addEventListener("click", () => {
          const content = scContent.value.trim();

          if (!content) {
            alert("请输入SC内容");
            return;
          }

          if (!selectedPrice) {
            alert("请选择金额");
            return;
          }

          if (!selectedColor) {
            alert("请选择颜色");
            return;
          }

          // 关闭SC弹窗
          closeScModal.click();

          // 发送SC消息
          sendSuperChat(content, selectedPrice, selectedColor);

          // 重置表单
          scContent.value = "";
          scContent.style.backgroundColor = "";
          scContent.style.borderColor = "";
          scPriceOptions.forEach((opt) => opt.classList.remove("selected"));
          scColorOptions.forEach((opt) => opt.classList.remove("selected"));
          selectedPrice = null;
          selectedColor = null;
        });

        // 发送SuperChat消息
        function sendSuperChat(content, price, color) {
          // 使用解析的用户ID，如果未找到则使用默认值
          const userName = window.currentUserID || "user的大手";

          // 创建SC消息元素
          const scMessage = document.createElement("div");
          scMessage.classList.add("sc-message");
          scMessage.style.backgroundColor = hexToRgba(color, 0.8);
          scMessage.style.color = getContrastColor(color);
          scMessage.style.top = `${getRandomPosition()}px`;

          // 创建SC消息内容
          scMessage.innerHTML = `
                    <div class="sc-message-header">
                        <div class="sc-message-user">${userName}</div>
                        <div class="sc-message-price">¥${price}</div>
                    </div>
                    <div class="sc-message-content">${content}</div>
                `;

          // 添加到SC消息容器
          scMessagesContainer.appendChild(scMessage);

          // 10秒后移除SC消息
          setTimeout(() => {
            scMessage.remove();
          }, 10000);

          // 播放提示音
          playScSound();

          // 发送SC弹幕
          addScDanmaku(content, price, color);

          // 与SillyTavern集成：使用全局函数发送SC信息
          try {
            window.sendToSillyTavern(`【直播醒目留言】${userName} 发送了 ¥${price} SC：${content}`);
            console.log('已向SillyTavern发送SC信息');
          } catch (error) {
            console.error('向SillyTavern发送SC信息失败:', error);
          }
        }

        // 添加SC弹幕
        function addScDanmaku(content, price, color) {
          // 使用解析的用户ID，如果未找到则使用默认值
          const userName = window.currentUserID || "user的大手";

          const container = document.querySelector(
            document
              .querySelector(".iphone-container")
              .classList.contains("landscape")
              ? ".landscape-danmaku"
              : ".portrait-danmaku"
          );

          const danmakuItem = document.createElement("div");
          danmakuItem.classList.add("danmaku-item");
          danmakuItem.style.background = `linear-gradient(90deg, ${hexToRgba(
            color,
            0.6
          )}, ${hexToRgba(color, 0.8)})`;
          danmakuItem.style.border = `1px solid ${hexToRgba(color, 0.9)}`;
          danmakuItem.style.boxShadow = `0 0 10px ${hexToRgba(color, 0.5)}`;

          if (container.classList.contains("portrait-danmaku")) {
            danmakuItem.innerHTML = `<span class="danmaku-user" style="color: yellow;">${userName} (¥${price})：</span><span class="danmaku-content">${content}</span>`;
          } else {
            danmakuItem.textContent = `${userName} (¥${price}): ${content}`;
            danmakuItem.style.top = `${Math.random() * 80}%`;
            danmakuItem.style.color = getContrastColor(color);
            danmakuItem.style.fontWeight = "bold";
          }

          container.appendChild(danmakuItem);

          setTimeout(() => {
            danmakuItem.remove();
          }, 10000);
        }

        // 获取随机位置
        function getRandomPosition() {
          // 计算手机屏幕上半部分的随机位置
          const phoneHeight = document
            .querySelector(".iphone-frame")
            .getBoundingClientRect().height;
          return 50 + Math.random() * (phoneHeight / 2 - 100); // 上半部分随机位置
        }

        // 播放SC提示音
        function playScSound() {
          const audioContext = new (window.AudioContext ||
            window.webkitAudioContext)();
          const oscillator = audioContext.createOscillator();
          const gainNode = audioContext.createGain();

          oscillator.type = "sine";
          oscillator.frequency.setValueAtTime(880, audioContext.currentTime); // A5
          oscillator.frequency.exponentialRampToValueAtTime(
            440,
            audioContext.currentTime + 0.2
          ); // A4

          gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
          gainNode.gain.exponentialRampToValueAtTime(
            0.01,
            audioContext.currentTime + 0.5
          );

          oscillator.connect(gainNode);
          gainNode.connect(audioContext.destination);

          oscillator.start();
          oscillator.stop(audioContext.currentTime + 0.5);
        }

        // 颜色工具函数
        function hexToRgba(hex, alpha = 1) {
          const r = parseInt(hex.slice(1, 3), 16);
          const g = parseInt(hex.slice(3, 5), 16);
          const b = parseInt(hex.slice(5, 7), 16);
          return `rgba(${r}, ${g}, ${b}, ${alpha})`;
        }

        function getContrastColor(hexColor) {
          const r = parseInt(hexColor.slice(1, 3), 16);
          const g = parseInt(hexColor.slice(3, 5), 16);
          const b = parseInt(hexColor.slice(5, 7), 16);

          // 计算亮度 (ITU-R BT.709)
          const luminance = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;

          // 返回黑色或白色作为对比色
          return luminance > 0.5 ? "#000000" : "#FFFFFF";
        }

        // 默认选中第一个价格和颜色选项
        if (scPriceOptions.length > 0) {
          scPriceOptions[0].click();
        }

        if (scColorOptions.length > 0) {
          scColorOptions[0].click();
        }
      });
    </script>
  </body>
</html>
